// Turns one setup-form submission into a ready clinic assistant (prompt, link, embed code).
const row = $input.first().json;
let b = {};
try { b = JSON.parse(row.payload_json || '{}'); } catch (e) { b = {}; }
const s = v => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, 600);
const list = v => Array.isArray(v) ? v.slice(0, 80) : [];
const name = s(b.clinic_name || row.clinic_name) || 'the clinic';
const assistant = s(b.assistant_name) || 'Noor';
const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 24) || 'clinic';
const token = Math.random().toString(36).slice(2, 8) + Math.random().toString(36).slice(2, 6);
const clinic_id = slug + '-' + token;
const days = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday'];
const hours = b.hours || {};
const hoursTxt = days.map(d => '- ' + d[0].toUpperCase() + d.slice(1) + ': ' + (s(hours[d]) || 'closed')).join('\n');
const services = list(b.services).filter(x => x && s(x.name));
const cur = s(b.currency) || 'AED';
const svcTxt = services.map(x => '- ' + s(x.name) + (s(x.price) === '0' ? ': free' : s(x.price) ? ': ' + (x.from ? 'from ' : '') + s(x.price) + ' ' + cur : ': price on consultation') + (s(x.minutes) ? ' (' + s(x.minutes) + ' min)' : '') + (s(x.doctor) ? ' - ' + s(x.doctor) : '')).join('\n') || '- (no services listed yet: offer to pass the question to the team)';
const docs = list(b.doctors).filter(x => x && s(x.name));
const docTxt = docs.map(x => '- ' + s(x.name) + (s(x.specialty) ? ', ' + s(x.specialty) : '') + (s(x.services) ? ' (' + s(x.services) + ')' : '') + (s(x.days) ? ', days: ' + s(x.days) : '') + (s(x.languages) ? ', speaks ' + s(x.languages) : '')).join('\n') || '- (not listed)';
const faqs = list(b.faqs).filter(x => x && s(x.q));
const faqTxt = faqs.map(x => 'Q: ' + s(x.q) + '\nA: ' + s(x.a)).join('\n') || '(none)';
const extra = [['Address', b.address], ['Map link', b.map_link], ['Parking', b.parking], ['Payment', b.payment], ['Insurance', b.insurance], ['Policies', b.policies], ['Cancellation', b.late_cancel_hours ? 'please cancel at least ' + s(b.late_cancel_hours) + ' hours before' : ''], ['Closed dates', b.closed_dates], ['Website', b.website], ['Clinic phone', b.support_phone || b.clinic_whatsapp]].filter(x => s(x[1])).map(x => '- ' + x[0] + ': ' + s(x[1])).join('\n');
const emergency = s(b.emergency_number) || '999';
const tone = s(b.tone) || 'warm, professional and brief';
const prompt = [
  'You are ' + assistant + ', the AI receptionist of ' + name + (s(b.clinic_type) ? ' (' + s(b.clinic_type) + ' clinic)' : '') + '. You chat with patients on the clinic website.',
  'Tone: ' + tone + '. Reply in the language the patient writes in (English or Arabic). Keep replies to 1-4 short sentences. No markdown headings.',
  '', 'CLINIC FACTS (the only facts you may use):', extra, '', 'Opening hours:', hoursTxt, '', 'Services and prices:', svcTxt, '', 'Doctors:', docTxt, '', 'FAQs:', faqTxt, '',
  'RULES:',
  '- Only use the facts above. If something is not listed, say you will check with the team and offer to take their name and phone so the clinic can reply.',
  '- Never diagnose or give medical advice. For severe pain, bleeding, swelling with fever or any emergency, tell them to call ' + emergency + ' or go to the nearest emergency room.',
  '- Never ask for ID numbers, card or payment details, or medical history.',
  '- You cannot see the live calendar. For appointments, collect: full name, phone number (WhatsApp), service, preferred day and time. Then tell them the clinic team will confirm the exact time shortly. Never say the booking is confirmed.',
  '- When you have all four booking details for the first time, add this on a new line at the very end of your reply, exactly once: [[REQUEST]]{"name":"...","phone":"...","service":"...","time":"...","note":"..."}[[/REQUEST]]',
  '- Prices are as listed; final price is confirmed by the doctor after examination.',
  '- If asked, you are an AI assistant for the clinic, powered by Halora.'
].join('\n');

const pkg = s(b.plan) || 'front-desk';
const yes = v => String(v || '').toLowerCase() === 'yes';
const f = { chat: true, portal: true,
  whatsapp: ['front-desk','front-desk-phone','group'].includes(pkg),
  phone: ['front-desk-phone','group'].includes(pkg) || yes(b.addon_phone),
  website: pkg === 'group' || yes(b.addon_website),
  reminders: pkg === 'group' || yes(b.addon_reminders) };
const features = Object.keys(f).filter(k => f[k]).join(',');
const portal_key = [0,1,2].map(() => Math.random().toString(36).slice(2, 10)).join('');
const site = { name, type: s(b.clinic_type), assistant, address: s(b.address), map: s(b.map_link), parking: s(b.parking), phone: s(b.support_phone || b.clinic_whatsapp || b.contact_phone), whatsapp: String(b.clinic_whatsapp || '').replace(/\D/g, ''), hours: days.map(d => [d, s(hours[d]) || 'closed']), services: services.map(x => ({ n: s(x.name), p: s(x.price), from: !!x.from, m: s(x.minutes) })), doctors: docs.map(x => ({ n: s(x.name), sp: s(x.specialty), d: s(x.days) })), faqs: faqs.map(x => ({ q: s(x.q), a: s(x.a) })), insurance: s(b.insurance), payment: s(b.payment), cur, review: s(b.google_review_link) };
const site_url = f.website ? 'https://askhalora.com/site/?c=' + clinic_id : '';
const portal_url = 'https://askhalora.com/portal/?c=' + clinic_id + '&k=' + portal_key;
const voice_prompt = prompt.replace('You chat with patients on the clinic website.', 'You answer the clinic phone. Speak naturally, short sentences, one question at a time. Read prices and times clearly.').replace(/- When you have all four booking details[^\n]*/, '- When you have the four booking details, repeat them back, then call the save_appointment_request tool once, then tell them the team will confirm shortly.');
const first_message = 'Hello, thank you for calling ' + name + '. This is ' + assistant + ', the virtual receptionist. How can I help you today?';
const steps = ['Owner portal: ' + portal_url];
if (f.website) steps.push('Website: ' + site_url);
if (f.phone) steps.push('Phone: voice agent created. TODO: buy a phone number and connect it in ElevenLabs.');
if (f.whatsapp) steps.push('WhatsApp: TODO: connect the clinic number in Meta (10 min with the clinic).');
const p = (d) => ({ type: 'string', description: d });
const agent_body = { name: 'Halora - ' + name, conversation_config: { agent: { first_message: first_message, language: 'en', prompt: { prompt: voice_prompt, tools: [{ type: 'webhook', name: 'save_appointment_request', description: 'Save the caller appointment request for the clinic team to confirm. Call once when you have name, phone, service and preferred time.', api_schema: { url: 'https://YOUR-INSTANCE.app.n8n.cloud/webhook/your-webhook-path?action=phone_request&c=' + clinic_id, method: 'POST', request_body_schema: { type: 'object', properties: { name: p('Caller full name'), phone: p('Caller phone number'), service: p('Treatment or service requested'), time: p('Preferred day and time'), note: p('Anything else the caller mentioned') }, required: ['name', 'phone', 'service', 'time'] } } }] } } } };
const welcome = 'Hi! I am ' + assistant + ', the assistant of ' + name + '. I can answer questions about our services, prices and hours, or take an appointment request. How can I help?';
const chat_url = 'https://askhalora.com/chat/?c=' + clinic_id;
const embed = '<iframe src="' + chat_url + '&embed=1" style="width:380px;height:560px;border:0;border-radius:16px" title="' + name.replace(/"/g, '') + ' assistant"></iframe>';
return [{ json: {
  clinic_id, clinic_name: name, intake_id: row.id, lang: s(b.lang) || 'en',
  alert_phone: '000000000000', clinic_phone: String(b.owner_phone || b.contact_phone || row.contact_phone || '').replace(/\D/g, ''),
  system_prompt: prompt, welcome, chat_url, embed,
  package: pkg, features, portal_key, site_url, portal_url, site_json: JSON.stringify(site), whatsapp_status: f.whatsapp ? 'needs_meta_connect' : 'not_in_package', wants_phone: f.phone, agent_body, voice_prompt, first_message, agent_name: 'Halora - ' + name, steps: steps.join('\n'),
  summary: services.length + ' services, ' + docs.length + ' doctors, ' + faqs.length + ' FAQs'
} }];

